def check_password(password):
    if len(password) < 8:
        return "弱い: 8文字以上必要です"
    elif password.isalnum():
        return "普通: 記号を含めると強化されます"
    else:
        return "強い: 安全なパスワードです"

print(check_password("abc123"))
